 "gram": "частина виразу «sudski tumač» (судовий перекладач)"}, {"form": "šalter", "lemma": "šalter", "ua": "віконце (в установі)", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "dolazite", "lemma": "dolaziti", "ua": "приходити", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: ви (і ввічливе «Ви»)"}, {"form": "s", "lemma": "s", "ua": "з (разом із)", "lesson": false, "pos": "прийменник «з»: + орудний — разом із («s obitelji»); + родовий — звідки («s Hvara», «s posla»)"}, {"form": "brojem", "lemma": "broj", "ua": "номер / число", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "орудний відмінок (ким? чим?), однина"}, {"form": "iz", "lemma": "iz", "ua": "з (звідки)", "lesson": true, "pos": "прийменник + родовий відмінок"}, {"form": "automata", "lemma": "automat", "ua": "автомат (паркомат, автомат з продажу)", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "родовий відмінок (кого? чого?), однина"}, {"form": "radno", "lemma": "radno vrijeme", "ua": "робочий час", "lesson": true, "pos": "сталий вираз", "gram": "с. р.: частина виразу «radno vrijeme»"}, {"form": "vrijeme", "lemma": "vrijeme", "ua": "погода / час", "lesson": true, "pos": "іменник, середній рід"}, {"form": "sati", "lemma": "sat", "ua": "годинник / година", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "родовий відмінок (кого? чого?), множина. Після 5 і більше: «osam sati»"}, {"form": "ako", "lemma": "ako", "ua": "якщо", "lesson": true, "pos": "сполучник"}, {"form": "ne", "lemma": "ne", "ua": "ні", "lesson": true, "pos": "частка"}, {"form": "razumijete", "lemma": "razumjeti", "ua": "розуміти", "lesson": true, "pos": "дієслово, доконаний і недоконаний вид", "gram": "теперішній час: ви (і ввічливе «Ви»)"}, {"form": "pitajte", "lemma": "pitati", "ua": "питати", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "наказовий спосіб: ви (зробіть!)"}, {"form": "šalteru", "lemma": "šalter", "ua": "віконце (в устан