  v_changed int;
  v_same int;
begin
  if (select count(*) from public.reading_texts r join jsonb_to_recordset(v_data) as g(code text, body_hr text, body_ua text, word_count int, glossary jsonb, known_ratio numeric) on g.code = r.code) < 11 then
    raise exception 'Не знайдено всіх текстів A1 (чи завантажено 20261014_reading_a1_v1.sql?)';
  end if;

  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  select 'reading_text', r.id, r.version,
         jsonb_build_object('code', r.code, 'body_hr', r.body_hr, 'body_ua', r.body_ua, 'word_count', r.word_count,
                            'glossary', r.glossary, 'known_ratio', r.known_ratio),
         'reading_a1_rewrite 2026-11-04: менше незнайомих слів (≥ 90 % знайомих, §56) — замінено 1–2 рідкісні слова або додано коротке речення; переклад оновлено, питання ті самі.'
  from public.reading_texts r
  join jsonb_to_recordset(v_data) as g(code text, body_hr text, body_ua text, word_count int, glossary jsonb, known_ratio numeric) on g.code = r.code
  where r.body_hr is distinct from g.body_hr or r.body_ua is distinct from g.body_ua
  on conflict (entity_type, entity_id, version) do nothing;

  with changed as (
    update public.reading_texts r
       set body_hr = g.body_hr, body_ua = g.body_ua, word_count = g.word_count,
           glossary = g.glossary, known_ratio = g.known_ratio, version = r.version + 1
      from jsonb_to_recordset(v_data) as g(code text, body_hr text, body_ua text, word_count int, glossary jsonb, known_ratio numeric)
     where g.code = r.code and (r.body_hr is distinct from g.body_hr or r.body_ua is distinct from g.body_ua)
    returning r.id, r.status
  ), logged as (
    insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
    select 'reading_text', c.id, c.status, c.status, 'auto_passed', 'ai', '[]'::jsonb, 'reading_a1_rewrite 2026-11-04: менше незнайомих слів (≥ 90 % знайомих, §56) — замінено 1–2 рідкісні слова або додано коротке речення; переклад оновлено, питання ті самі.'
    from changed c
    returning 1
  )
  select count(*) into v_changed from logged;

  select count(*) into v_same
    from public.reading_texts r
    join jsonb_to_recordset(v_data) as g(code text, body_hr text, body_ua text, word_count int, glossary jsonb, known_ratio numeric) on g.code = r.code
   where r.body_hr = g.body_hr and r.body_ua = g.body_ua and r.known_ratio >= 0.9;
  if v_same < 11 then raise exception 'Оновлено текстів %, очікувалось 11', v_same; end if;
  raise notice 'Готово: 11 текстів A1 оновлено (змінено зараз: %)', v_changed;
end
